with filtered as (select id, store_name, city, region, opened_date, sqft, trim(store_name) as clean_store_name, coalesce(region, 'NONE') as region_filled from stores where store_name like 'Ma%') select id, city, sqft, sum(sqft) over (partition by city order by sqft, id rows between unbounded preceding and current row) as running_sqft, ntile(4) over (partition by city order by sqft, id) as sqft_bucket from filtered where lower(trim(store_name)) = 'mall central';
